function fmtDate(d) {
  const w = WD_L[LANG][d.getDay()];
  if (MONTHS_L[LANG]) return d.getDate() + ' ' + MONTHS_L[LANG][d.getMonth()] + ' (' + w + ')';
  if (LANG === 'en') return MONTHS_EN[d.getMonth()] + ' ' + d.getDate() + ' (' + w + ')';
  return (d.getMonth() + 1) + '月' + d.getDate() + '日（' + w + '）';
}
function fmtShort(d) {
  const w = WD_L[LANG][d.getDay()];
  if (MONTHS_L[LANG]) return d.getDate() + ' ' + MONTHS_L[LANG][d.getMonth()] + ' (' + w + ')';
  if (LANG === 'en') return (d.getMonth() + 1) + '/' + d.getDate() + ' (' + w + ')';
  return (d.getMonth() + 1) + '/' + d.getDate() + '（' + w + '）';
}
function rankStr(n) {
  if (LANG === 'en') return 'No. ' + n;
  if (LANG === 'zh') return '第' + n + '名';
  if (LANG === 'ja') return '第' + n + '位';
  return RANK_WORD[LANG](n);
}
function avgRankStr(m, a) {
  if (LANG === 'en') return 'Avg. rank in ' + MONTHS_EN[m - 1] + ': ' + a;
  if (LANG === 'zh') return m + '月平均排名 ' + a + ' 名';
  if (LANG === 'ja') return m + '月の平均順位 ' + a + ' 位';
  return AVG_WORD[LANG](a, MONTHS_L[LANG][m - 1]);
}
